"""Writes src/styles.ts from the CSS files (Aurora's base + the Pulsar sections)."""
import json, pathlib
src = pathlib.Path(__file__).parent / 'src'
read = lambda n: (src / n).read_text()
css = read('aurora.css') + '\n' + read('landing.css')
editor = read('aurora-editor.css') + '\n' + read('landing.css')
(src / 'styles.ts').write_text(
    '// Generated by build-styles.py from aurora.css, aurora-editor.css and landing.css.\n'
    f'export const css = {json.dumps(css)};\nexport const editorCss = {json.dumps(editor)};\n')
